// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetOIDCConfiguration OIDC discovery (base issuer)
	// (GET /.well-known/openid-configuration)
	GetOIDCConfiguration(ctx context.Context, request GetOIDCConfigurationRequestObject) (GetOIDCConfigurationResponseObject, error)
	// GetJWKS Issuer signing keys
	// (GET /jwks)
	GetJWKS(ctx context.Context, request GetJWKSRequestObject) (GetJWKSResponseObject, error)
	// GetTenantOIDCConfiguration OIDC discovery (per-tenant issuer `…/t/{tenant}`)
	// (GET /t/{tenant}/.well-known/openid-configuration)
	GetTenantOIDCConfiguration(ctx context.Context, request GetTenantOIDCConfigurationRequestObject) (GetTenantOIDCConfigurationResponseObject, error)
	// GetTenantJWKS Per-tenant issuer signing keys (same key set)
	// (GET /t/{tenant}/jwks)
	GetTenantJWKS(ctx context.Context, request GetTenantJWKSRequestObject) (GetTenantJWKSResponseObject, error)
	// ListAudit Query audit records
	// (GET /v1/audit)
	ListAudit(ctx context.Context, request ListAuditRequestObject) (ListAuditResponseObject, error)
	// AppendAudit Append a batch of host audit records
	// (POST /v1/audit)
	AppendAudit(ctx context.Context, request AppendAuditRequestObject) (AppendAuditResponseObject, error)
	// GetAuditVerification Verify every audit chain
	// (GET /v1/audit/verification)
	GetAuditVerification(ctx context.Context, request GetAuditVerificationRequestObject) (GetAuditVerificationResponseObject, error)
	// GetCertificate Look up a node certificate by stable node ID
	// (GET /v1/certificates/{stableNodeID})
	GetCertificate(ctx context.Context, request GetCertificateRequestObject) (GetCertificateResponseObject, error)
	// ListDeployments List deployments
	// (GET /v1/deployments)
	ListDeployments(ctx context.Context, request ListDeploymentsRequestObject) (ListDeploymentsResponseObject, error)
	// CreateDeployment Deploy a workload (async), or preflight it with dryRun
	// (POST /v1/deployments)
	CreateDeployment(ctx context.Context, request CreateDeploymentRequestObject) (CreateDeploymentResponseObject, error)
	// DeleteDeployment Undeploy
	// (DELETE /v1/deployments/{id})
	DeleteDeployment(ctx context.Context, request DeleteDeploymentRequestObject) (DeleteDeploymentResponseObject, error)
	// GetDeployment Read a deployment and its status
	// (GET /v1/deployments/{id})
	GetDeployment(ctx context.Context, request GetDeploymentRequestObject) (GetDeploymentResponseObject, error)
	// GetDeploymentBundle Download the raw bundle
	// (GET /v1/deployments/{id}/bundle)
	GetDeploymentBundle(ctx context.Context, request GetDeploymentBundleRequestObject) (GetDeploymentBundleResponseObject, error)
	// CreateDeviceDeleteRun Run the scheduled device deletes now
	// (POST /v1/device-delete-runs)
	CreateDeviceDeleteRun(ctx context.Context, request CreateDeviceDeleteRunRequestObject) (CreateDeviceDeleteRunResponseObject, error)
	// GetHealthz Liveness
	// (GET /v1/healthz)
	GetHealthz(ctx context.Context, request GetHealthzRequestObject) (GetHealthzResponseObject, error)
	// ListHosts List hosts
	// (GET /v1/hosts)
	ListHosts(ctx context.Context, request ListHostsRequestObject) (ListHostsResponseObject, error)
	// CreateHost Add a host and mint its single-use join key
	// (POST /v1/hosts)
	CreateHost(ctx context.Context, request CreateHostRequestObject) (CreateHostResponseObject, error)
	// DeleteHost Drain and remove a host
	// (DELETE /v1/hosts/{id})
	DeleteHost(ctx context.Context, request DeleteHostRequestObject) (DeleteHostResponseObject, error)
	// GetHost Read a host
	// (GET /v1/hosts/{id})
	GetHost(ctx context.Context, request GetHostRequestObject) (GetHostResponseObject, error)
	// RegisterHost Register or re-register a host (idempotent)
	// (PUT /v1/hosts/{id})
	RegisterHost(ctx context.Context, request RegisterHostRequestObject) (RegisterHostResponseObject, error)
	// ListHostAssignments List the deployments assigned to a host
	// (GET /v1/hosts/{id}/assignments)
	ListHostAssignments(ctx context.Context, request ListHostAssignmentsRequestObject) (ListHostAssignmentsResponseObject, error)
	// ReportHostStatus Heartbeat (replace the host's reported status)
	// (PUT /v1/hosts/{id}/status)
	ReportHostStatus(ctx context.Context, request ReportHostStatusRequestObject) (ReportHostStatusResponseObject, error)
	// ListObjects List objects (with lineage)
	// (GET /v1/objects)
	ListObjects(ctx context.Context, request ListObjectsRequestObject) (ListObjectsResponseObject, error)
	// CreateObject Create an object (async mint)
	// (POST /v1/objects)
	CreateObject(ctx context.Context, request CreateObjectRequestObject) (CreateObjectResponseObject, error)
	// DeleteObject Kill an object
	// (DELETE /v1/objects/{id})
	DeleteObject(ctx context.Context, request DeleteObjectRequestObject) (DeleteObjectResponseObject, error)
	// GetObject Read an object (lineage, children, kill record)
	// (GET /v1/objects/{id})
	GetObject(ctx context.Context, request GetObjectRequestObject) (GetObjectResponseObject, error)
	// UpdateObject Update an object (JSON Merge Patch)
	// (PATCH /v1/objects/{id})
	UpdateObject(ctx context.Context, request UpdateObjectRequestObject) (UpdateObjectResponseObject, error)
	// GetObjectCertificate Read the object's node certificate
	// (GET /v1/objects/{id}/certificate)
	GetObjectCertificate(ctx context.Context, request GetObjectCertificateRequestObject) (GetObjectCertificateResponseObject, error)
	// CreateObjectCredential Mint a single-use auth key for the object's node
	// (POST /v1/objects/{id}/credentials)
	CreateObjectCredential(ctx context.Context, request CreateObjectCredentialRequestObject) (CreateObjectCredentialResponseObject, error)
	// GetStatus mgmt status
	// (GET /v1/status)
	GetStatus(ctx context.Context, request GetStatusRequestObject) (GetStatusResponseObject, error)
	// ListTenants List tenants
	// (GET /v1/tenants)
	ListTenants(ctx context.Context, request ListTenantsRequestObject) (ListTenantsResponseObject, error)
	// CreateTenant Create a tenant
	// (POST /v1/tenants)
	CreateTenant(ctx context.Context, request CreateTenantRequestObject) (CreateTenantResponseObject, error)
	// DeleteTenant Delete a tenant
	// (DELETE /v1/tenants/{id})
	DeleteTenant(ctx context.Context, request DeleteTenantRequestObject) (DeleteTenantResponseObject, error)
	// GetTenant Read a tenant
	// (GET /v1/tenants/{id})
	GetTenant(ctx context.Context, request GetTenantRequestObject) (GetTenantResponseObject, error)
	// UpdateTenant Update a tenant (JSON Merge Patch)
	// (PATCH /v1/tenants/{id})
	UpdateTenant(ctx context.Context, request UpdateTenantRequestObject) (UpdateTenantResponseObject, error)
	// PurgeTenantObjects Purge terminal objects of a tenant
	// (DELETE /v1/tenants/{id}/objects)
	PurgeTenantObjects(ctx context.Context, request PurgeTenantObjectsRequestObject) (PurgeTenantObjectsResponseObject, error)
	// CheckTenantWIF Verify a wif tenant's trust credentials (diagnostic)
	// (POST /v1/tenants/{id}/wif-check)
	CheckTenantWIF(ctx context.Context, request CheckTenantWIFRequestObject) (CheckTenantWIFResponseObject, error)
	// CreateVolumeKeyGrant Release a volume's dm-crypt data key to the lease holder
	// (POST /v1/volumes/{id}/keys)
	CreateVolumeKeyGrant(ctx context.Context, request CreateVolumeKeyGrantRequestObject) (CreateVolumeKeyGrantResponseObject, error)
	// WhoAmI Who the caller is, as mgmt sees it
	// (GET /v1/whoami)
	WhoAmI(ctx context.Context, request WhoAmIRequestObject) (WhoAmIResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

